182		Fix $\mathsf{ldparams} = (q,m,d,k)$. Answers in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
183		\begin{itemize}
184			\item Type $\mathsf{Point}$, question content $u \in \F_q^m$: the answer is an element of $\F_q^k$.
185			\item Type $\mathsf{ALine}$, question content $(u_0,s) \in \F_q^m \times \F_q$, specifying the axis-parallel line $\ell(u_0,e_i)$ with $i = \chi(s)$: the answer is a $k$-tuple $(f_1,\ldots,f_k)$ of univariate polynomials $f_j\colon \F_q \to \F_q$ of degree at most $d$, each given by its $d+1$ coefficients.
186			\item Type $\mathsf{DLine}$, question content $(u_0,s,v) \in \F_q^m \times \F_q \times \F_q^m$, specifying the diagonal line $\ell(u_0,v')$ with $v' = \pi_{i-1}(v)$ and $i = \chi(s)$: the answer is a $k$-tuple of univariate polynomials of degree at most $md$.
187		\end{itemize}
188		The win predicate $D^{\mathrm{ld}} = D^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A,\mathrm B\}$; in all cases where no action is indicated, the predicate accepts.
189		\begin{enumerate}
190			\item (\textbf{Consistency test}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
191			% The source phrases both clauses with "the" t such that x = u_0 + tv; that phrase
192			% does not determine t on diagonal questions with direction v' = 0, which the
193			% question distribution samples with positive probability. The universal
194			% quantification over t used here is the local correction; see the remark below.
195			\item (\textbf{Axis-parallel line-versus-point test}) If $t_w = \mathsf{ALine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t e_i$, where $i = \chi(s)$.
196			\item (\textbf{Diagonal line-versus-point test}) If $t_w = \mathsf{DLine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t v'$, where $v' = \pi_{i-1}(v)$ and $i = \chi(s)$.
197		\end{enumerate}
198		The game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{ld}}$, the question distribution of Definition~\ref{def:ld-question-distribution}, and win predicate $D^{\mathrm{ld}}_{\mathsf{ldparams}}$.
199	\end{definition}
200	
201	\begin{remark}[Diagonal questions with zero direction]\label{rem:ld-win-zero-direction}
202		The source states the two line-versus-point clauses with ``the'' $t \in \F_q$ such that $x_{\overline w} = u_0 + t v$. When the direction is nonzero and $x_{\overline w}$ lies on the line, exactly one such $t$ exists and the formulation above agrees with the source. But zero directions occur: Definition~\ref{def:line} explicitly permits them, and the question distribution of Definition~\ref{def:ld-question-distribution} produces $\mathsf{DLine}$ questions with $v' = \pi_{i-1}(v) = 0$ with positive probability, namely whenever the last $m - i + 1$ coordinates of $v$ vanish. In that case $\ell(u_0, 0) = \{u_0\}$, every $t \in \F_q$ satisfies $x_{\overline w} = u_0 + t v'$ when $x_{\overline w} = u_0$, and the source clause does not determine acceptance for a nonconstant answer polynomial. The universal quantification over $t$ adopted in Definition~\ref{def:ld-win-predicate} makes the predicate a well-defined function of its arguments; it accepts vacuously when no such $t$ exists, a case the question distribution never produces. Completeness is unaffected: the restriction of a polynomial $g$ to the singleton line $\ell(u_0,0)$, expressed through the parameterization $t \mapsto u_0 + t \cdot 0$, is the constant polynomial with value $g(u_0)$, which passes the check for every $t$. Soundness is likewise unaffected: zero directions occur with probability at most $2/(mq)$, so any acceptance convention on this event changes success probabilities by at most that amount; the game-correspondence obligation enumerated in the proof of Theorem~\ref{lem:ld-soundness} accounts for this event explicitly, and an error of this shape is absorbed into the universal constants of $\delta_{\mathrm{ld}}$.
203	\end{remark}
204	
205	The soundness properties of the low individual degree game are expressed in terms of the following class of measurements.
206	
207	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
208		\lean{MIPStarRE.QPBT.PolyIndex, MIPStarRE.QPBT.PolyMeas, MIPStarRE.QPBT.PolyMeasFamily, MIPStarRE.QPBT.PolyMeasTuple}
209		\leanok
210		\uses{def:polyfunc, def:polymeasurements, def:polynomials-degree}
211		Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements indexed by $\polyfunc{m}{q}{d}$, the polynomial representatives of individual degree at most $d$ in each variable; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). By Definition~\ref{def:polynomials-degree}, evaluation identifies these representatives with the corresponding polynomial functions $g\colon \F_q^m \to \F_q$, bijectively whenever $d \le q-1$; at the canonical parameters (Definition~\ref{def:introparams}, where $d = 1 \le q-1$) the identification is bijective; the general statements of this chapter quantify over all admissible tuples and are read through the representative convention. More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
212		The tuple components are labelled by $r\in\{0,\ldots,k-1\}$, with
213		label $r$ representing the paper's component $r+1$.
214	\end{definition}
